index pending_session: CREATE INDEX pending_session on pending(account, room, session)
table devices: CREATE TABLE devices (account text not null primary key, device text not null, since text not null default '', created integer not null)
table files: CREATE TABLE files (account text not null, url text not null, file text not null, created integer not null, primary key (account, url))
table identities: CREATE TABLE identities (account text not null, person text not null, device integer not null, key text not null, trust text not null default '', created integer not null, primary key (account, person, device))
table lists: CREATE TABLE lists (account text not null, person text not null, version text not null, devices text not null, fetched integer not null, primary key (account, person, version))
table omemo: CREATE TABLE omemo (account text not null primary key, device integer not null, identity text not null, next integer not null, created integer not null)
table opened: CREATE TABLE opened (account text not null, digest text not null, body text not null, created integer not null, primary key (account, digest))
table pending: CREATE TABLE pending (account text not null, room text not null, session text not null, event text not null, created integer not null)
table prekeys: CREATE TABLE prekeys (account text not null, id integer not null, key text not null, primary key (account, id))
table sessions: CREATE TABLE sessions (account text not null, version text not null, person text not null, device integer not null, state text not null, updated integer not null, primary key (account, version, person, device))
table signed: CREATE TABLE signed (account text not null, id integer not null, key text not null, legacy text not null, current text not null, created integer not null, primary key (account, id))
